import json
import os
import pandas as pd

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/polymers.xlsx"

df = pd.read_excel(DATA_FILE, sheet_name="PE")
df.columns = [str(c).strip() for c in df.columns]

x_col = next(c for c in df.columns if "Temperature" in c)
y_col = next(c for c in df.columns if "Weight" in c and "Deriv" not in c)
dy_col = next(c for c in df.columns if "Deriv" in c)

data = []
for x, y in zip(pd.to_numeric(df[x_col], errors="coerce"),
                pd.to_numeric(df[y_col], errors="coerce")):
    if pd.notna(x) and pd.notna(y):
        data.append([float(x), float(y)])

deriv_data = []
for x, y in zip(pd.to_numeric(df[x_col], errors="coerce"),
                pd.to_numeric(df[dy_col], errors="coerce")):
    if pd.notna(x) and pd.notna(y):
        deriv_data.append([float(x), float(y)])

option = {
    "animation": False,
    "title": {
        "text": "PE TGA",
        "left": "center",
        "textStyle": {"fontFamily": "Noto Sans CJK KR"}
    },
    "tooltip": {"trigger": "axis"},
    "legend": {"data": ["Weight (%)", "Deriv. Weight (%/°C)"], "top": 32},
    "grid": {"left": 75, "right": 75, "top": 85, "bottom": 65},
    "xAxis": {
        "type": "value",
        "name": "Temperature (°C)",
        "min": 100,
        "max": 700,
        "interval": 100,
        "nameLocation": "middle",
        "nameGap": 38,
        "axisLabel": {"fontFamily": "Noto Sans CJK KR"},
        "nameTextStyle": {"fontFamily": "Noto Sans CJK KR"}
    },
    "yAxis": [
        {
            "type": "value",
            "name": "Weight (%)",
            "min": 0,
            "max": 110,
            "nameLocation": "middle",
            "nameGap": 48,
            "axisLabel": {"fontFamily": "Noto Sans CJK KR"},
            "nameTextStyle": {"fontFamily": "Noto Sans CJK KR"}
        },
        {
            "type": "value",
            "name": "Deriv. Weight (%/°C)",
            "nameLocation": "middle",
            "nameGap": 52,
            "axisLabel": {"fontFamily": "Noto Sans CJK KR"},
            "nameTextStyle": {"fontFamily": "Noto Sans CJK KR"}
        }
    ],
    "series": [
        {
            "name": "Weight (%)",
            "type": "line",
            "data": data,
            "yAxisIndex": 0,
            "showSymbol": False,
            "lineStyle": {"color": "#ff0000", "width": 3},
            "itemStyle": {"color": "#ff0000"}
        },
        {
            "name": "Deriv. Weight (%/°C)",
            "type": "line",
            "data": deriv_data,
            "yAxisIndex": 1,
            "showSymbol": False,
            "lineStyle": {"color": "#3569a8", "width": 1.5},
            "itemStyle": {"color": "#3569a8"}
        }
    ]
}

print(json.dumps({
    "figures": [{
        "name": "PE_TGA",
